+-- KG V1 B0 query projection views and local rehearsal object counts.
+-- Issue: #1288. Parent: #1278.
+-- DRAFT ONLY. No remote mutation. Local/disposable rehearsal only.
+-- Required psql usage:
+--   psql "$DISPOSABLE_DATABASE_URL" \
+--     -v target_project_ref=<new-or-local-project-ref> \
+--     -f artifacts/supabase-audit/v1-9709-kg-b0-rehearsal/02-kg-b0-query-projection-views.local-disposable-only.sql
+
+\set ON_ERROR_STOP on
+\if :{?target_project_ref}
+\else
+\echo 'ERROR: target_project_ref is required. Refusing to run draft projection SQL.'
+do $missing_target_project_ref$
+begin
+  raise exception 'target_project_ref is required. Refusing to run draft projection SQL.';
+end
+$missing_target_project_ref$;
+\endif
+
+begin;
+
+select set_config('app.rehearsal_target_project_ref', :'target_project_ref', true);
+select set_config('app.archive_project_ref', 'nbzvlqtgnkmohlamguzz', true);
+
+do $guard$
+declare
+  target_ref text := current_setting('app.rehearsal_target_project_ref', true);
+  archive_ref text := current_setting('app.archive_project_ref', true);
+begin
+  if target_ref is null or btrim(target_ref) = '' then
+    raise exception 'target_project_ref guard missing';
+  end if;
+
+  if target_ref = archive_ref then
+    raise exception 'refusing to run B0 projection draft against archive project %', archive_ref;
+  end if;
+end
+$guard$;
+
+-- Per-surface projection views are intentionally private-only.
+
+drop view if exists private.kg_v1_b0_query_projection_question_runtime_availability;
+drop view if exists private.kg_v1_b0_query_projection_visual_dependency_and_receipt;
+drop view if exists private.kg_v1_b0_query_projection_student_display_eligibility;
+drop view if exists private.kg_v1_b0_query_projection_diagnostic_posture_and_evidence_reason;
